<?php require __DIR__.'/../app/bootstrap.php';if(!empty($_SESSION['user_id'])){header('Location:/dashboard.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location:/dashboard.php');exit;}flash('error','Invalid email or password.');header('Location:/login.php');exit;}require __DIR__.'/../app/layout.php';header_html('Login');?><div class="auth card"><img src="/logo.jpg" class="auth-logo"><h2>Login</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form><p>No account? <a href="/register.php">Create one</a></p></div><?php footer_html();
